"""English request -> program pairs for the OLED language, generated by rules and checked by the interpreter.

Each family is one kind of easy thing a person asks a matchbox-sized screen for (write a word, count down, draw a
circle, a frame, stripes, a moving dot, a progress bar…). A family draws its parameters, phrases the request one
of several ways, and writes the program in one of a few styles. Every program is run by lang.run before it is
kept: it must parse, stay in the language, finish in time and light at least one pixel.

Writes data/oled/pairs.jsonl: {prompt, program, family, doc}. doc is what the model learns:
"# <request>\\n<program>", ended later by the tokenizer's end-of-text.

    python -m research.oled.gen --n 300000
"""
import argparse
import json
import random
import sys
from pathlib import Path

from .lang import CW, H, W, LangError, run

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "data" / "oled" / "pairs.jsonl"

WORDS = ["hello", "hi", "yes", "no", "ok", "go", "stop", "cat", "dog", "sun", "moon", "love", "code", "wow",
         "hello world", "good morning", "good night", "welcome", "ready", "done", "error", "loading", "boom",
         "on", "off", "play", "pause", "win", "lose", "home", "coffee", "tea", "matchbox", "esp32", "kate"]
NUMWORD = {1: "one", 2: "two", 3: "three", 4: "four", 5: "five", 6: "six", 7: "seven", 8: "eight", 9: "nine",
           10: "ten"}
SPEED = [("quickly", 100), ("fast", 150), ("", 300), ("slowly", 600), ("very slowly", 1000)]
VAR = ["i", "n", "k", "x"]


def pick(r, xs):
    return r.choice(xs)


def num(r, n):
    """A number as a person might type it."""
    return NUMWORD[n] if n in NUMWORD and r.random() < 0.4 else str(n)


def cx(s):
    return max(0, (W - CW * len(s)) // 2)


def place(r):
    """A position for text: (phrase, x of a function of the string, y)."""
    return pick(r, [("in the middle", "mid", 28), ("in the center", "mid", 28), ("at the top", "mid", 0),
                    ("at the bottom", "mid", 56), ("in the top left corner", 0, 0), ("on the left", 0, 28),
                    ("", "mid", 28)])


def f_text(r):
    w = pick(r, WORDS)
    where, x, y = place(r)
    x = cx(w) if x == "mid" else x
    verb = pick(r, ["write", "show", "display", "print", "put"])
    q = pick(r, ['"', "", ""])
    prompt = f"{verb} {q}{w}{q}" + (f" {where}" if where else "") + pick(r, ["", " on the screen"])
    if r.random() < 0.15:
        prompt = pick(r, [f"say {w}", f"the screen should say {w}", f"{w} on the screen"])
        x, y = cx(w), 28
    return prompt, f'clear()\ntext({x}, {y}, "{w}")\n'


def f_two_lines(r):
    a, b = r.sample(WORDS, 2)
    prompt = pick(r, [f"write {a} and under it {b}", f"show {a} on the first line and {b} on the second",
                      f"two lines: {a} and {b}"])
    return prompt, f'clear()\ntext({cx(a)}, 20, "{a}")\ntext({cx(b)}, 36, "{b}")\n'


def f_count(r):
    up = r.random() < 0.5
    n = r.randint(3, 10)
    sp, ms = pick(r, SPEED)
    v = pick(r, VAR)
    end = r.random() < 0.4
    fin = pick(r, ["GO", "done", "boom", "end", "ready"])
    if up:
        prompt = pick(r, [f"count from 1 to {num(r, n)}", f"count to {num(r, n)}", f"count up to {num(r, n)}"])
        rng = f"range(1, {n + 1})"
    else:
        prompt = pick(r, [f"count down from {num(r, n)}", f"countdown from {num(r, n)}", f"count down from {num(r, n)} to 1"])
        rng = f"range({n}, 0, -1)"
    if sp:
        prompt += " " + sp
    if end:
        prompt += pick(r, [f" then show {fin}", f" and then write {fin}", f", then say {fin}"])
    prog = f"for {v} in {rng}:\n    clear()\n    text(60, 28, str({v}))\n    wait({ms})\n"
    if end:
        prog += f'clear()\ntext({cx(fin)}, 28, "{fin}")\n'
    return prompt, prog


def f_circle(r):
    rad = r.randint(4, 30)
    where = pick(r, [("in the middle", 64, 32), ("in the center", 64, 32), ("on the left", 32, 32),
                     ("on the right", 96, 32), ("", 64, 32)])
    size = pick(r, [(f"with radius {rad}", rad), ("small", 8), ("big", 28), ("", 20)])
    prompt = pick(r, ["draw", "make", "show"]) + " a " + (size[0] + " " if size[0] and not size[0].startswith("with") else "") + "circle"
    if size[0].startswith("with"):
        prompt += " " + size[0]
    if where[0]:
        prompt += " " + where[0]
    return prompt, f"clear()\ncircle({where[1]}, {where[2]}, {size[1]})\n"


def f_frame(r):
    prompt = pick(r, ["draw a frame around the screen", "draw a border", "make a box around the edge",
                      "draw a rectangle around the whole screen", "border around the screen"])
    return prompt, f"clear()\nrect(0, 0, {W}, {H})\n"


def f_box(r):
    w, h = r.randint(10, 60), r.randint(8, 40)
    filled = r.random() < 0.4
    prompt = pick(r, ["draw", "make"]) + (" a filled" if filled else " a") + pick(r, [f" box {w} by {h}", f" rectangle {w} wide and {h} tall"])
    centered = r.random() < 0.6
    x, y = ((W - w) // 2, (H - h) // 2) if centered else (0, 0)
    prompt += " in the middle" if centered else " in the corner"
    return prompt, f"clear()\n{'fill' if filled else 'rect'}({x}, {y}, {w}, {h})\n"


def f_lines(r):
    kind = pick(r, ["diagonal", "cross", "x", "horizontal", "vertical"])
    if kind == "diagonal":
        return pick(r, ["draw a diagonal line", "draw a line from the top left to the bottom right"]), "clear()\nline(0, 0, 127, 63)\n"
    if kind == "x":
        return pick(r, ["draw an X", "draw a big X across the screen", "cross out the screen"]), "clear()\nline(0, 0, 127, 63)\nline(0, 63, 127, 0)\n"
    if kind == "cross":
        return pick(r, ["draw a plus in the middle", "draw a cross in the center"]), "clear()\nline(64, 0, 64, 63)\nline(0, 32, 127, 32)\n"
    n = r.randint(2, 8)
    v = pick(r, VAR)
    if kind == "horizontal":
        gap = H // (n + 1)
        return (pick(r, [f"draw {num(r, n)} horizontal lines", f"{num(r, n)} lines across the screen"]),
                f"clear()\nfor {v} in range({n}):\n    y = {gap} + {v} * {gap}\n    line(0, y, 127, y)\n")
    gap = W // (n + 1)
    return (pick(r, [f"draw {num(r, n)} vertical lines", f"{num(r, n)} lines from top to bottom"]),
            f"clear()\nfor {v} in range({n}):\n    x = {gap} + {v} * {gap}\n    line(x, 0, x, 63)\n")


def f_stripes(r):
    n = pick(r, [4, 8, 16])
    v = pick(r, VAR)
    if r.random() < 0.5:
        prompt = pick(r, ["draw vertical stripes", f"draw {num(r, n)} vertical stripes" if n <= 10 else "draw thin vertical stripes"])
        w = W // n
        return prompt, f"clear()\nfor {v} in range(0, {n}, 2):\n    fill({v} * {w}, 0, {w}, 64)\n"
    prompt = pick(r, ["draw horizontal stripes", f"draw {num(r, n)} horizontal stripes" if n <= 10 else "draw thin horizontal stripes"])
    h = H // n
    return prompt, f"clear()\nfor {v} in range(0, {n}, 2):\n    fill(0, {v} * {h}, 128, {h})\n"


def f_grid(r):
    step = pick(r, [8, 16, 32])
    prompt = pick(r, ["draw a grid", f"draw a grid every {step} pixels", "draw graph paper"])
    if "every" not in prompt:
        step = 16
    return prompt, (f"clear()\nfor x in range(0, 128, {step}):\n    line(x, 0, x, 63)\n"
                    f"for y in range(0, 64, {step}):\n    line(0, y, 127, y)\n")


def f_rings(r):
    n = r.randint(2, 6)
    v = pick(r, VAR)
    prompt = pick(r, [f"draw {num(r, n)} circles inside each other", f"{num(r, n)} rings in the middle", f"draw a target with {num(r, n)} rings"])
    step = 30 // n
    return prompt, f"clear()\nfor {v} in range(1, {n + 1}):\n    circle(64, 32, {v} * {step})\n"


def f_dots(r):
    n = r.randint(3, 12)
    v = pick(r, VAR)
    gap = W // (n + 1)
    prompt = pick(r, [f"draw {num(r, n)} dots in a row", f"put {num(r, n)} dots across the middle"])
    return prompt, f"clear()\nfor {v} in range({n}):\n    fill({gap} + {v} * {gap} - 1, 31, 3, 3)\n"


def f_smiley(r):
    prompt = pick(r, ["draw a smiley", "draw a smiley face", "make a happy face", "draw a face"])
    return prompt, ("clear()\ncircle(64, 32, 24)\nfill(54, 22, 4, 4)\nfill(70, 22, 4, 4)\n"
                    "line(54, 42, 58, 46)\nline(58, 46, 70, 46)\nline(70, 46, 74, 42)\n")


def f_move(r):
    sp, ms = pick(r, SPEED[:3])
    ms = max(30, ms // 3)
    v = pick(r, VAR)
    what = pick(r, [("dot", "fill({v}, 30, 4, 4)"), ("ball", "circle({v}, 32, 4)"), ("square", "fill({v}, 26, 12, 12)")])
    direction = pick(r, ["left to right", "right to left"])
    rng = "range(0, 124, 4)" if direction == "left to right" else "range(124, 0, -4)"
    prompt = pick(r, [f"move a {what[0]} from {direction}", f"animate a {what[0]} going from {direction}",
                      f"a {what[0]} that slides from {direction}"]) + (" " + sp if sp else "")
    return prompt, f"for {v} in {rng}:\n    clear()\n    {what[1].format(v=v)}\n    wait({ms})\n"


def f_bounce(r):
    n = r.randint(2, 4)
    prompt = pick(r, ["bounce a ball", f"bounce a ball {num(r, n)} times", "a ball bouncing left and right"])
    if "times" not in prompt:
        n = 3
    return prompt, (f"x = 4\nd = 4\nhits = 0\nwhile hits < {n * 2}:\n    clear()\n    circle(x, 32, 4)\n    wait(30)\n"
                    f"    x = x + d\n    if x > 123 or x < 4:\n        d = -d\n        hits = hits + 1\n")


def f_grow(r):
    v = pick(r, VAR)
    prompt = pick(r, ["grow a circle", "a circle that gets bigger", "make a circle grow from the middle", "animate a growing circle"])
    return prompt, f"for {v} in range(1, 31, 2):\n    clear()\n    circle(64, 32, {v})\n    wait(60)\n"


def f_blink(r):
    w = pick(r, WORDS)
    n = r.randint(2, 6)
    sp, ms = pick(r, SPEED)
    v = pick(r, VAR)
    prompt = pick(r, [f"blink {w} {num(r, n)} times", f"flash {w} {num(r, n)} times", f"make {w} blink {num(r, n)} times"]) + (" " + sp if sp else "")
    return prompt, f'for {v} in range({n}):\n    clear()\n    text({cx(w)}, 28, "{w}")\n    wait({ms})\n    clear()\n    wait({ms})\n'


def f_progress(r):
    sp, ms = pick(r, SPEED[:4])
    ms = max(20, ms // 5)
    v = pick(r, VAR)
    label = r.random() < 0.4
    prompt = pick(r, ["fill a progress bar", "show a loading bar", "draw a progress bar that fills up"]) + (" " + sp if sp else "")
    prog = "clear()\n" + ('text(40, 20, "loading")\n' if label else "") + "rect(4, 28, 120, 10)\n"
    if label:
        prompt += pick(r, [" with the word loading", " and write loading above it"])
    prog += f"for {v} in range(0, 117, 4):\n    fill(6, 30, {v}, 6)\n    wait({ms})\n"
    return prompt, prog


def f_scroll(r):
    w = pick(r, WORDS)
    v = pick(r, VAR)
    prompt = pick(r, [f"scroll {w} across the screen", f"make {w} move from right to left", f"slide {w} across"])
    return prompt, f'for {v} in range(128, -{CW * len(w)}, -4):\n    clear()\n    text({v}, 28, "{w}")\n    wait(40)\n'


def f_boxed_word(r):
    w = pick(r, WORDS)
    x = cx(w)
    prompt = pick(r, [f"write {w} in a box", f"write {w} and draw a box around it", f"{w} with a frame around it"])
    return prompt, f'clear()\ntext({x}, 28, "{w}")\nrect({x - 4}, 24, {CW * len(w) + 7}, 16)\n'


def f_circle_word(r):
    w = pick(r, WORDS)
    prompt = pick(r, [f"draw a circle and write {w} under it", f"a circle with {w} below it"])
    return prompt, f'clear()\ncircle(64, 22, 16)\ntext({cx(w)}, 48, "{w}")\n'


def f_count_then_shape(r):
    n = r.randint(3, 5)
    shape = pick(r, [("a circle", "circle(64, 32, 20)"), ("a smiley", "circle(64, 32, 24)\nfill(54, 22, 4, 4)\nfill(70, 22, 4, 4)\nline(54, 42, 58, 46)\nline(58, 46, 70, 46)\nline(70, 46, 74, 42)"),
                         ("an X", "line(0, 0, 127, 63)\nline(0, 63, 127, 0)")])
    prompt = pick(r, [f"count down from {num(r, n)} and then draw {shape[0]}", f"countdown from {num(r, n)}, then show {shape[0]}"])
    return prompt, f"for i in range({n}, 0, -1):\n    clear()\n    text(60, 28, str(i))\n    wait(500)\nclear()\n{shape[1]}\n"


def f_numbers_list(r):
    n = r.randint(3, 8)
    v = pick(r, VAR)
    prompt = pick(r, [f"write the numbers 1 to {n} in a column", f"list the numbers from 1 to {num(r, n)} down the screen"])
    return prompt, f"clear()\nfor {v} in range(1, {n + 1}):\n    text(0, ({v} - 1) * 8, str({v}))\n"


def f_squares(r):
    n = r.randint(3, 8)
    v = pick(r, VAR)
    prompt = pick(r, [f"write the squares of 1 to {n}", f"show {num(r, n)} square numbers"])
    return prompt, f'clear()\nfor {v} in range(1, {n + 1}):\n    text(0, ({v} - 1) * 8, str({v}) + " x " + str({v}) + " = " + str({v} * {v}))\n'


def f_even_numbers(r):
    n = r.randint(10, 20)
    v = pick(r, VAR)
    which = pick(r, ["even", "odd"])
    rem = 0 if which == "even" else 1
    prompt = pick(r, [f"show the {which} numbers up to {n}", f"write all {which} numbers from 1 to {n}"])
    return prompt, (f'clear()\nline_text = ""\nfor {v} in range(1, {n + 1}):\n    if {v} % 2 == {rem}:\n'
                    f'        line_text = line_text + str({v}) + " "\ntext(0, 28, line_text)\n')


def f_staircase(r):
    n = r.randint(3, 7)
    v = pick(r, VAR)
    s = 64 // n
    prompt = pick(r, [f"draw a staircase with {num(r, n)} steps", f"{num(r, n)} stairs going up"])
    return prompt, f"clear()\nfor {v} in range({n}):\n    fill({v} * {s * 2}, 64 - ({v} + 1) * {s}, {s * 2}, ({v} + 1) * {s})\n"


def f_checker(r):
    prompt = pick(r, ["draw a checkerboard", "draw a chess board pattern", "checker pattern"])
    return prompt, ("clear()\nfor y in range(0, 64, 8):\n    for x in range(0, 128, 8):\n"
                    "        if (x // 8 + y // 8) % 2 == 0:\n            fill(x, y, 8, 8)\n")


FAMILIES = [f_text, f_two_lines, f_count, f_circle, f_frame, f_box, f_lines, f_stripes, f_grid, f_rings, f_dots,
            f_smiley, f_move, f_bounce, f_grow, f_blink, f_progress, f_scroll, f_boxed_word, f_circle_word,
            f_count_then_shape, f_numbers_list, f_squares, f_even_numbers, f_staircase, f_checker]


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--n", type=int, default=300_000)
    ap.add_argument("--seed", type=int, default=0)
    args = ap.parse_args()
    r = random.Random(args.seed)
    seen, rows, bad = set(), [], {}
    for _ in range(args.n):
        fam = pick(r, FAMILIES)
        prompt, prog = fam(r)
        prompt = " ".join(prompt.split())
        if r.random() < 0.3:
            prompt = prompt[0].upper() + prompt[1:]
        key = (prompt, prog)
        if key in seen:
            continue
        seen.add(key)
        try:
            s = run(prog)
            assert any(sum(f) for _, f in s.frames), "nothing drawn"
        except (LangError, AssertionError) as e:
            bad[fam.__name__] = bad.get(fam.__name__, 0) + 1
            continue
        rows.append({"prompt": prompt, "program": prog, "family": fam.__name__[2:], "doc": f"# {prompt}\n{prog}"})
    OUT.parent.mkdir(parents=True, exist_ok=True)
    with open(OUT, "w") as f:
        for row in rows:
            f.write(json.dumps(row) + "\n")
    print(f"{len(rows):,} unique pairs from {args.n:,} draws, {len(FAMILIES)} families; failed checks: {bad or 'none'}")


if __name__ == "__main__":
    sys.exit(main())
